class Dog {
    String name;
    Dog(String name) { this.name = name; }
}

static void modifyPrimitive(int value) {
    value = 99; // zmienia TYLKO lokalna kopie
}

static void modifyObject(Dog dog) {
    dog.name = "Reksio"; // zmienia obiekt NA HEAPIE - widoczne na zewnatrz!
}

// W main():
int localPrimitive = 10;
Dog dog1 = new Dog("Azor");

modifyPrimitive(localPrimitive);
System.out.println(localPrimitive); // WCIAZ 10 - oryginal nietkniety

modifyObject(dog1);
System.out.println(dog1.name); // "Reksio" - obiekt ZMODYFIKOWANY

dog1 = null; // usuwamy jedyna referencje
System.gc(); // TYLKO sugestia dla JVM, nie gwarancja

exercises.solution:
int x = 10;
System.out.println(x);
// x jest typem prymitywnym - jego wartosc jest przechowywana BEZPOSREDNIO
// w ramce stosu metody main(), bez potrzeby alokacji na heapie.

StringBuilder sb = new StringBuilder("Hello");
System.out.println(sb);
// Referencja 'sb' zyje na stosie (jako lokalna zmienna metody),
// ale sam obiekt StringBuilder("Hello") jest na stercie (heap), utworzony przez 'new'.

int original = 5;
doubleValue(original);
System.out.println("Po wywolaniu: " + original); // wciaz 5

static void doubleValue(int x) {
    x = x * 2;
    System.out.println("W metodzie: " + x);
}

int[] arr = {1, 2, 3};
addTen(arr);
System.out.println(arr[0]); // 11 - zmienione!

static void addTen(int[] a) {
    a[0] = a[0] + 10;
}

int a = 5;
int b = a;
b = 99;
System.out.println("a = " + a); // 5 - niezmienione
System.out.println("b = " + b); // 99
// Przypisanie int b = a KOPIUJE WARTOSC (nie referencje) - a i b sa
// od tej pory calkowicie NIEZALEZNYMI zmiennymi na stosie.

int[] arr1 = {1, 2, 3};
int[] arr2 = arr1;
arr2[0] = 99;
System.out.println(arr1[0]); // 99 - zmienione!
// arr1 i arr2 to DWIE ROZNE zmienne (referencje), ale obie wskazuja
// na TEN SAM obiekt tablicy na heapie - modyfikacja przez arr2 jest
// widoczna tez przez arr1.

String s = null;
System.out.println("s == null: " + (s == null));
try {
    int len = s.length();
} catch (NullPointerException e) {
    System.out.println("Zlapano NullPointerException");
}

Object obj = new Object();
System.out.println(obj);
obj = null;
System.gc();
System.out.println("GC zasugerowany");

recurse(10);

static void recurse(int n) {
    System.out.println("n = " + n);
    if (n > 0) {
        recurse(n - 1);
    }
}
// Rekurencja BEZ warunku zatrzymania (base case) wywolywalaby siebie
// w nieskonczonosc, wyczerpujac pojemnosc stosu i rzucajac StackOverflowError.

StringBuilder sb1 = new StringBuilder("Hello");
StringBuilder sb2 = sb1;
sb2.append(" World");
System.out.println(sb1); // "Hello World" - zmienione tez przez sb1!

String s1 = "Hello";
String s2 = s1;
s1 = s1 + " World";
System.out.println("s1: " + s1); // "Hello World"
System.out.println("s2: " + s2); // "Hello" - niezmienione!
// s1 = s1 + " World" tworzy NOWY obiekt String i przypisuje go do s1.
// s2 WCIAZ wskazuje na STARY, oryginalny obiekt "Hello".

int result = calculate(3, 4);
System.out.println(result); // 7

static int calculate(int a, int b) {
    int result = a + b;
    return result;
}
// Wywolanie tworzy ramke stosu z lokalnymi zmiennymi a, b, result -
// po zwroceniu wartosci ramka jest natychmiast usuwana ze stosu.

static class Box {
    int value;
    Box(int v) { value = v; }
}

static void increment(Box b) {
    b.value++;
}

// W main():
Box box = new Box(10);
increment(box);
System.out.println(box.value); // 11

int[] original = {1, 2, 3};
reassign(original);
System.out.println(original[0]); // WCIAZ 1 - niezmienione!

static void reassign(int[] arr) {
    arr = new int[]{99, 98, 97};
}
// arr w metodzie to LOKALNA kopia referencji - przypisanie do niej
// nowego obiektu NIE wplywa na oryginalna zmienna 'original' z main().

Runtime runtime = Runtime.getRuntime();
System.out.println("Total: " + runtime.totalMemory() / 1024 / 1024 + " MB");
System.out.println("Free: " + runtime.freeMemory() / 1024 / 1024 + " MB");
System.out.println("Max: " + runtime.maxMemory() / 1024 / 1024 + " MB");

int x = 10, y = 20;
swapPrimitives(x, y);
System.out.println("x = " + x + ", y = " + y); // WCIAZ x=10, y=20

static void swapPrimitives(int a, int b) {
    int temp = a;
    a = b;
    b = temp;
}
// Metoda zamienia TYLKO swoje LOKALNE kopie a i b - x i y w main()
// pozostaja niezmienione, bo Java przekazuje prymitywy przez wartosc.

String a = "test";
String b = new String("test");
System.out.println(a == b);       // false
System.out.println(a.equals(b));  // true
// String Pool to WYDZIELONY obszar heapa przechowujacy WSPOLDZIELONE
// literaly - a wskazuje na obiekt z puli, b to OSOBNY obiekt utworzony
// jawnie przez 'new', POZA pula, mimo identycznej tresci.

Integer a = 100, b = 100;
Integer c = 200, d = 200;
System.out.println(a == b); // true - w zakresie cache (-128..127)
System.out.println(c == d); // false - poza zakresem cache, dwa rozne obiekty
// Java cachuje obiekty Integer dla wartosci -128..127 (Integer Cache) -
// autoboxowanie w tym zakresie zwraca WSPOLNY obiekt z cache, poza
// zakresem KAZDE autoboxowanie tworzy NOWY obiekt na heapie.

StringBuilder[] builders = new StringBuilder[5];
for (int i = 0; i < 5; i++) {
    builders[i] = new StringBuilder("Builder " + i);
    System.out.println(builders[i]);
}
for (int i = 0; i < 5; i++) {
    builders[i] = null;
}
System.gc();
// Obiekty StringBuilder utracily wszystkie referencje - staly sie
// kandydatami do usuniecia przez Garbage Collector.

StringBuilder[] builders = new StringBuilder[3];
builders[0] = new StringBuilder("A");
builders[1] = new StringBuilder("B");
builders[2] = new StringBuilder("C");
for (StringBuilder b : builders) {
    System.out.println(b);
}
// Tablica 'builders' (przechowujaca referencje) jest OBIEKTEM na heapie,
// a kazdy StringBuilder, na ktory wskazuje jej element, to OSOBNY obiekt
// TEZ na heapie - dwie odrebne alokacje.

System.out.println(factorial(5));

static int factorial(int n) {
    System.out.println("Wywolanie factorial(" + n + ")");
    if (n <= 1) {
        return 1;
    }
    return n * factorial(n - 1);
}

Runtime runtime = Runtime.getRuntime();
StringBuilder[] arr = new StringBuilder[1000];
for (int i = 0; i < 1000; i++) {
    arr[i] = new StringBuilder("Element " + i);
}
System.out.println("Free przed: " + runtime.freeMemory());

for (int i = 0; i < 500; i++) {
    arr[i] = null;
}
System.out.println("Free po nullowaniu: " + runtime.freeMemory());

System.gc();
System.out.println("Free po GC: " + runtime.freeMemory());

int[][] matrix = {{1, 2}, {3, 4}};
int[][] shallow = matrix;
shallow[0][0] = 99;
System.out.println(matrix[0][0]); // 99 - zmienione!
// Plytka kopia (shallow copy) kopiuje TYLKO referencje - shallow i matrix
// wskazuja na TEN SAM obiekt tablicy. Glebia kopia (deep copy) wymagalaby
// stworzenia CALKOWICIE NOWYCH tablic wewnetrznych, niezaleznych od oryginalu.

static class Counter {
    static int count = 0;
    int id;
    Counter() {
        count++;
        id = count;
    }
}

// W main():
Counter c1 = new Counter();
Counter c2 = new Counter();
Counter c3 = new Counter();
System.out.println("c1.id=" + c1.id + ", count=" + Counter.count);
System.out.println("c2.id=" + c2.id + ", count=" + Counter.count);
System.out.println("c3.id=" + c3.id + ", count=" + Counter.count);
// Pole static 'count' jest WSPOLNE dla wszystkich instancji Counter -
// kazdy obiekt widzi TA SAMA, aktualna wartosc.

System.out.println(safeLength("hello")); // 5
System.out.println(safeLength(null));      // 0
System.out.println(safeLength(""));        // 0

static int safeLength(String s) {
    if (s == null) {
        return 0;
    }
    return s.length();
}

StringBuilder sb1 = new StringBuilder("abc");
StringBuilder sb2 = new StringBuilder("abc");
System.out.println(sb1 == sb2);                       // false - rozne obiekty
System.out.println(sb1.toString().equals(sb2.toString())); // true - ta sama zawartosc
// StringBuilder NIE przeciaza equals() (dziedziczy z Object, zachowuje sie
// jak ==) - do porownania ZAWARTOSCI trzeba najpierw skonwertowac na String.

StringBuilder sb = new StringBuilder();
sb.append("Java").append(" ").append("2025").append("!");
System.out.println(sb);
// Kazda metoda append() zwraca 'this' (referencje do TEGO SAMEGO obiektu
// na heapie) - dlatego mozna od razu wywolac kolejna metode na wyniku,
// tworzac 'lancuch' (method chaining) bez tworzenia posrednich zmiennych.

Runtime runtime = Runtime.getRuntime();
System.out.println("Free przed: " + runtime.freeMemory());

int[] arr = new int[1000000];
System.out.println("Free po tablicy: " + runtime.freeMemory());

String s = "Hello";
System.out.println("Free po Stringu: " + runtime.freeMemory());

arr = null;
s = null;
System.gc();
System.out.println("Free po GC: " + runtime.freeMemory());

a();

static void a() {
    b();
}

static void b() {
    c();
}

static void c() {
    new RuntimeException("Slad stosu").printStackTrace();
}
// Wydruk pokaze pelny lancuch wywolan: c() <- b() <- a() <- main(),
// odzwierciedlajac dokladnie stan stosu w momencie wywolania.

Runtime runtime = Runtime.getRuntime();

long startTime1 = System.currentTimeMillis();
String result = "";
for (int i = 0; i < 10000; i++) {
    result += i;
}
long time1 = System.currentTimeMillis() - startTime1;

long startTime2 = System.currentTimeMillis();
StringBuilder sb = new StringBuilder();
for (int i = 0; i < 10000; i++) {
    sb.append(i);
}
long time2 = System.currentTimeMillis() - startTime2;

System.out.println("String +: " + time1 + " ms");
System.out.println("StringBuilder: " + time2 + " ms");

